description:
Objective:
Pure beads-Dolt separation guard: a Loreweaver campaign Dolt directory must never
be equal to, nested within, or a parent of the beads Dolt repo, and must not use
the beads ref namespace. Offline, no Dolt binary needed.

Files:
- Create: `packages/core/src/persistence/checkpoint/separation.ts`
- Modify: `packages/core/src/index.ts`
- Test:   `packages/core/test/checkpoint.separation.test.ts`

Steps:

1. Write the failing test `packages/core/test/checkpoint.separation.test.ts`:
```ts
import { describe, expect, it } from 'vitest';
import {
  SeparationError,
  assertSeparateFromBeads,
  BEADS_RESERVED_REF,
} from '../src/persistence/checkpoint/separation.js';

describe('beads-Dolt separation guard', () => {
  it('allows a clearly disjoint dolt dir', () => {
    expect(() =>
      assertSeparateFromBeads('/proj/.loreweaver/dolt', '/proj/.beads'),
    ).not.toThrow();
  });

  it('rejects a dolt dir equal to the beads dir', () => {
    expect(() => assertSeparateFromBeads('/proj/.beads', '/proj/.beads')).toThrow(
      SeparationError,
    );
  });

  it('rejects a dolt dir nested inside the beads dir', () => {
    expect(() =>
      assertSeparateFromBeads('/proj/.beads/dolt', '/proj/.beads'),
    ).toThrow(SeparationError);
  });

  it('rejects a dolt dir that contains the beads dir', () => {
    expect(() => assertSeparateFromBeads('/proj', '/proj/.beads')).toThrow(
      SeparationError,
    );
  });

  it('exposes the reserved beads ref so callers never reuse it', () => {
    expect(BEADS_RESERVED_REF).toBe('refs/dolt/data');
  });
});
```

2. Run it to verify FAIL.
   Command: `npx vitest run packages/core/test/checkpoint.separation.test.ts`
   Expected: FAIL — module not found.

3. Create `packages/core/src/persistence/checkpoint/separation.ts`:
```ts
import { resolve, relative, isAbsolute } from 'node:path';

export const BEADS_RESERVED_REF = 'refs/dolt/data';

export class SeparationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SeparationError';
  }
}

function isInside(child: string, parent: string): boolean {
  const rel = relative(parent, child);
  return rel === '' || (!rel.startsWith('..') && !isAbsolute(rel));
}

export function assertSeparateFromBeads(
  doltDir: string,
  beadsDir: string,
): void {
  const a = resolve(doltDir);
  const b = resolve(beadsDir);
  if (a === b || isInside(a, b) || isInside(b, a)) {
    throw new SeparationError(
      `Loreweaver Dolt dir ${a} must be disjoint from beads Dolt dir ${b}`,
    );
  }
}
```

4. Add to `packages/core/src/index.ts` (append):
```ts
export {
  SeparationError,
  assertSeparateFromBeads,
  BEADS_RESERVED_REF,
} from './persistence/checkpoint/separation.js';
```

5. Run the test to verify PASS.
   Command: `npx vitest run packages/core/test/checkpoint.separation.test.ts`
   Expected: 5 passed.

6. Typecheck.
   Command: `npm run build`
   Expected: exit 0.

7. Commit.
   Command: `git add -A && git commit -m "feat(e8): beads-Dolt separation guard"`
